package com.chromascape.web.integration.micro6.service;

import static org.assertj.core.api.Assertions.assertThat;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;

/**
 * Proves ChromaScape's canonical hashing matches the Micro6 executor byte-for-byte. The golden
 * values below were generated by compiling the real Micro6 {@code CanonicalJson} + {@code
 * CatalogV2Publication} hash functions and running them over the same fixed catalog input.
 */
class Micro6CanonicalHashTest {
  private static final ObjectMapper MAPPER = new ObjectMapper();

  private static final String GOLDEN_CATALOG_HASH =
      "sha256:17b13670b40dba066bb869aa2d80dbaaf8f83c76113d8a53d201794ce02d5ad4";
  private static final String GOLDEN_SETTINGS_SCHEMA_HASH =
      "sha256:95d587eacd8492a5f65e56e34fcf6085ab0c85aa2643da7f69823b9be0cf0957";
  private static final String GOLDEN_SCHEMA_BUNDLE_HASH =
      "sha256:93e263fa9413599010166a886f710579b056ab72487ff8fa8fab6fac7f0f073f";

  private static ObjectNode fishingTask(boolean withSchema) {
    ObjectNode task = MAPPER.createObjectNode();
    task.put("key", "FISHING_TRAINING");
    task.put("task_key", "FISHING_TRAINING");
    task.put("name", "Fishing Training");
    task.put("display_name", "Fishing Training");
    task.put("panel_display_name", "Fishing Training");
    task.put("category", "fishing");
    task.put("category_family", "fishing");
    task.put("enabled", true);
    task.put("runnable", true);
    task.put("task_type", "SKILLING");
    task.put("type", "SKILLING");
    ArrayNode searchAliases = MAPPER.createArrayNode();
    searchAliases.add("Fish Training");
    task.set("search_aliases", searchAliases);
    task.put("stability_tier", "standard");
    ArrayNode tags = MAPPER.createArrayNode();
    tags.add("fishing");
    tags.add("training");
    task.set("tags", tags);
    task.put("membership", "FREE");
    task.put("primary_skill", "FISHING");
    task.put("description", "Train Fishing through configured spots.");
    if (withSchema) {
      task.put("settings_schema_state", "AVAILABLE");
      task.put("settings_schema_version", "1");
      task.put("settings_schema_hash", GOLDEN_SETTINGS_SCHEMA_HASH);
      task.set("args_schema", fishingSchema());
    }
    return task;
  }

  private static ObjectNode fishingSchema() {
    ObjectNode schema = MAPPER.createObjectNode();
    schema.put("version", 1);
    schema.put("type", "object");
    ArrayNode fields = MAPPER.createArrayNode();
    ObjectNode stop = MAPPER.createObjectNode();
    stop.put("key", "stopConditionValue");
    stop.put("label", "Stop Condition Value");
    stop.put("type", "integer");
    stop.put("min", 1);
    stop.put("max", 99);
    stop.put("default", 50);
    fields.add(stop);
    ObjectNode fish = MAPPER.createObjectNode();
    fish.put("key", "targetFish");
    fish.put("label", "Target Fish");
    fish.put("type", "select");
    fish.put("default", "TROUT");
    ArrayNode options = MAPPER.createArrayNode();
    options.add("TROUT");
    options.add("SALMON");
    options.add("LOBSTER");
    fish.set("options", options);
    fields.add(fish);
    schema.set("fields", fields);
    return schema;
  }

  private static ObjectNode lightweightPayload() {
    ObjectNode payload = MAPPER.createObjectNode();
    payload.put("version", "2");
    payload.put("catalog_mode", "LIGHTWEIGHT");
    payload.put("catalog_state", "READY");
    payload.put("catalog_valid", true);
    payload.put("catalog_version", "2");
    payload.put("capability_version", "micro6-executor/v1");
    payload.put("catalog_hash", GOLDEN_CATALOG_HASH);
    ArrayNode tasks = MAPPER.createArrayNode();
    tasks.add(fishingTask(false));
    payload.set("tasks", tasks);
    payload.set("aliases", aliases());
    return payload;
  }

  private static ArrayNode aliases() {
    ObjectNode alias = MAPPER.createObjectNode();
    alias.put("alias", "FISH_TRAINING");
    alias.put("normalized_alias", "FISH_TRAINING");
    alias.put("task_key", "FISHING_TRAINING");
    ArrayNode aliases = MAPPER.createArrayNode();
    aliases.add(alias);
    return aliases;
  }

  private static ObjectNode fullPayload() {
    ObjectNode payload = lightweightPayload();
    payload.put("catalog_mode", "FULL");
    ArrayNode tasks = MAPPER.createArrayNode();
    tasks.add(fishingTask(true));
    payload.set("tasks", tasks);
    payload.put("catalog_hash", GOLDEN_CATALOG_HASH);
    payload.put("schema_bundle_hash", GOLDEN_SCHEMA_BUNDLE_HASH);
    return payload;
  }

  @Test
  void catalogHashMatchesMicro6GoldenValue() {
    assertThat(Micro6CanonicalHash.catalogHash(lightweightPayload(), "micro6-executor/v1"))
        .isEqualTo(GOLDEN_CATALOG_HASH);
  }

  @Test
  void catalogHashIsIdenticalForLightweightAndFullCatalogs() {
    assertThat(Micro6CanonicalHash.catalogHash(lightweightPayload(), "micro6-executor/v1"))
        .isEqualTo(Micro6CanonicalHash.catalogHash(fullPayload(), "micro6-executor/v1"));
  }

  @Test
  void catalogHashIsStableAcrossTaskOrdering() {
    ObjectNode first = lightweightPayload();
    ObjectNode reversed = lightweightPayload();
    ArrayNode reversedTasks = MAPPER.createArrayNode();
    reversedTasks.add(fishingTask(false));
    reversed.set("tasks", reversedTasks);
    assertThat(Micro6CanonicalHash.catalogHash(first, "micro6-executor/v1"))
        .isEqualTo(Micro6CanonicalHash.catalogHash(reversed, "micro6-executor/v1"));
  }

  @Test
  void catalogHashChangesWhenTaskIdentityChanges() {
    ObjectNode changed = lightweightPayload();
    ((ObjectNode) changed.path("tasks").get(0)).put("display_name", "Renamed Fishing");
    assertThat(Micro6CanonicalHash.catalogHash(changed, "micro6-executor/v1"))
        .isNotEqualTo(GOLDEN_CATALOG_HASH);
  }

  @Test
  void catalogHashIgnoresVolatileAndSchemaFields() {
    ObjectNode withVolatile = lightweightPayload();
    withVolatile.put("generated_at", "2026-01-01T00:00:00Z");
    withVolatile.put("login_state", "LOGGED_IN");
    withVolatile.put("queue_state", "QUEUED");
    assertThat(Micro6CanonicalHash.catalogHash(withVolatile, "micro6-executor/v1"))
        .isEqualTo(GOLDEN_CATALOG_HASH);
  }

  @Test
  void settingsSchemaHashMatchesMicro6GoldenValue() {
    assertThat(Micro6CanonicalHash.settingsSchemaHash(fishingSchema()))
        .isEqualTo(GOLDEN_SETTINGS_SCHEMA_HASH);
  }

  @Test
  void settingsSchemaHashChangesWhenSchemaChanges() {
    ObjectNode changed = fishingSchema();
    ((ObjectNode) changed.path("fields").get(0)).put("max", 50);
    assertThat(Micro6CanonicalHash.settingsSchemaHash(changed))
        .isNotEqualTo(GOLDEN_SETTINGS_SCHEMA_HASH);
  }

  @Test
  void schemaBundleHashMatchesMicro6GoldenValue() {
    String catalogHash = Micro6CanonicalHash.catalogHash(fullPayload(), "micro6-executor/v1");
    assertThat(Micro6CanonicalHash.schemaBundleHash(fullPayload(), catalogHash))
        .isEqualTo(GOLDEN_SCHEMA_BUNDLE_HASH);
  }

  @Test
  void schemaBundleHashBindsToCatalogHash() {
    String catalogHash = Micro6CanonicalHash.catalogHash(fullPayload(), "micro6-executor/v1");
    String bundle = Micro6CanonicalHash.schemaBundleHash(fullPayload(), catalogHash);
    assertThat(bundle)
        .isNotEqualTo(
            Micro6CanonicalHash.schemaBundleHash(fullPayload(), "sha256:" + "0".repeat(64)));
  }

  @Test
  void canonicalHashingRoundTripsThroughJson() throws Exception {
    JsonNode parsed = MAPPER.readTree(MAPPER.writeValueAsString(lightweightPayload()));
    assertThat(Micro6CanonicalHash.catalogHash(parsed, "micro6-executor/v1"))
        .isEqualTo(GOLDEN_CATALOG_HASH);
  }
}
